async function run(name,args,cwd=root,env={}){
  const previous=journal.find(step=>step.name===name);
  if(previous?.code===0){console.log('RETAIN '+name);return;}
  let attempts=previous?.attempts??[];
  if(previous){const archived={...previous};delete archived.attempts;const suffix='attempt'+(attempts.length+1);archived.log=name+'-'+suffix+'.log';copyFileSync(output+'/'+name+'.log',output+'/'+archived.log);for(const ext of ['.json','.json.timed.json'])if(existsSync(output+'/'+name+ext))copyFileSync(output+'/'+name+ext,output+'/'+name+'-'+suffix+ext);attempts=[...attempts,archived];journal.splice(journal.indexOf(previous),1);}
  const step={name,args,cwd,env,startedAt:new Date().toISOString(),...(attempts.length?{attempts}:{})};journal.push(step);
  writeFileSync(`${output}/execution.json`,JSON.stringify(journal,null,2));
  console.log(`START ${name}`);
  const log=openSync(`${output}/${name}.log`,'w');
  try{await new Promise((done,fail)=>{const child=spawn(process.execPath,args,{cwd,env:{...process.env,...env},stdio:['ignore',log,log],windowsHide:true});step.pid=child.pid;child.once('error',fail);child.once('exit',(code,signal)=>{step.code=code;step.signal=signal;code===0?done():fail(new Error(`${name} failed: ${code ?? signal}`));});});}
  finally{closeSync(log);step.endedAt=new Date().toISOString();writeFileSync(`${output}/execution.json`,JSON.stringify(journal,null,2));}
  console.log(`DONE ${name}`);
}
